package cyberpanel

import (
	"context"
	"database/sql"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"strconv"
	"strings"
	"time"

	"github.com/aonsyed/cyberpanel/platform/internal/migration"
)

type SQLLogicalDumper struct { database *sql.DB; maximumObjects,maximumRows uint64; maximumValueBytes int }
type sqlQueryer interface{QueryContext(context.Context,string,...any)(*sql.Rows,error)}
func NewSQLLogicalDumper(database *sql.DB,maximumObjects,maximumRows uint64,maximumValueBytes int)(*SQLLogicalDumper,error){if database==nil{return nil,ErrInvalid};if maximumObjects==0{maximumObjects=1_000_000};if maximumRows==0{maximumRows=1_000_000_000};if maximumValueBytes==0{maximumValueBytes=1<<30};if maximumObjects<1||maximumRows<1||maximumValueBytes<1<<20{return nil,ErrInvalid};return &SQLLogicalDumper{database:database,maximumObjects:maximumObjects,maximumRows:maximumRows,maximumValueBytes:maximumValueBytes},nil}

func(d *SQLLogicalDumper)WriteLogicalDump(ctx context.Context,request DatabaseDumpRequest,destination io.Writer)(uint64,error){if d==nil||d.database==nil||ctx==nil||destination==nil||!validDatabaseName(request.Name){return 0,ErrInvalid};transaction,err:=d.database.BeginTx(ctx,&sql.TxOptions{Isolation:sql.LevelRepeatableRead,ReadOnly:true});if err!=nil{return 0,err};defer transaction.Rollback();schema:=quoteSQLIdentifier(request.Name);charset:=safeSQLToken(request.Charset,"utf8mb4");collation:=safeSQLToken(request.Collation,"utf8mb4_unicode_ci");if _,err:=fmt.Fprintf(destination,"-- CyberPanel canonical logical dump v1\nSET FOREIGN_KEY_CHECKS=0;\nSET UNIQUE_CHECKS=0;\nCREATE DATABASE IF NOT EXISTS %s CHARACTER SET %s COLLATE %s;\nUSE %s;\n",schema,charset,collation,schema);err!=nil{return 0,err};rows,err:=transaction.QueryContext(ctx,`SELECT TABLE_NAME,TABLE_TYPE FROM information_schema.TABLES WHERE TABLE_SCHEMA=? ORDER BY CASE TABLE_TYPE WHEN 'BASE TABLE' THEN 0 ELSE 1 END,TABLE_NAME`,request.Name);if err!=nil{return 0,err};type relation struct{name,kind string};relations:=[]relation{};for rows.Next(){var value relation;if err:=rows.Scan(&value.name,&value.kind);err!=nil{rows.Close();return 0,err};if !validDatabaseName(value.name){rows.Close();return 0,ErrInvalid};relations=append(relations,value)};if err:=rows.Err();err!=nil{rows.Close();return 0,err};rows.Close();objects,totalRows:=uint64(1),uint64(0);for _,value:=range relations{if value.kind!="BASE TABLE"{continue};if objects>=d.maximumObjects{return 0,migrationCapacityError()};create,err:=d.showCreate(ctx,transaction,"TABLE",request.Name,value.name);if err!=nil{return 0,err};if _,err:=fmt.Fprintf(destination,"DROP TABLE IF EXISTS %s;\n%s;\n",quoteSQLIdentifier(value.name),trimSQLTerminator(create));err!=nil{return 0,err};objects++;rowsWritten,err:=d.writeTableRows(ctx,transaction,request.Name,value.name,destination,d.maximumRows-totalRows);if err!=nil{return 0,err};totalRows+=rowsWritten;if totalRows>d.maximumRows{return 0,migrationCapacityError()}};for _,value:=range relations{if value.kind=="BASE TABLE"{continue};create,err:=d.showCreate(ctx,transaction,"VIEW",request.Name,value.name);if err!=nil{return 0,err};if _,err:=fmt.Fprintf(destination,"DROP VIEW IF EXISTS %s;\n%s;\n",quoteSQLIdentifier(value.name),trimSQLTerminator(create));err!=nil{return 0,err};objects++;if objects>d.maximumObjects{return 0,migrationCapacityError()}};count,err:=d.writeTriggers(ctx,transaction,request.Name,destination);if err!=nil{return 0,err};objects+=count;count,err=d.writeRoutines(ctx,transaction,request.Name,destination);if err!=nil{return 0,err};objects+=count;count,err=d.writeEvents(ctx,transaction,request.Name,destination);if err!=nil{return 0,err};objects+=count;if objects>d.maximumObjects||objects>^uint64(0)-totalRows{return 0,migrationCapacityError()};_,err=io.WriteString(destination,"SET UNIQUE_CHECKS=1;\nSET FOREIGN_KEY_CHECKS=1;\n");if err!=nil{return 0,err};if err:=transaction.Commit();err!=nil{return 0,err};return objects+totalRows,nil}

func(d *SQLLogicalDumper)showCreate(ctx context.Context,queryer sqlQueryer,kind,database,name string)(string,error){query:="SHOW CREATE "+kind+" "+quoteSQLIdentifier(database)+"."+quoteSQLIdentifier(name);rows,err:=queryer.QueryContext(ctx,query);if err!=nil{return"",err};defer rows.Close();if !rows.Next(){if err:=rows.Err();err!=nil{return"",err};return"",sql.ErrNoRows};values,err:=scanStringRow(rows);if err!=nil{return"",err};for _,value:=range values{upper:=strings.ToUpper(strings.TrimSpace(value));if strings.HasPrefix(upper,"CREATE ")||strings.Contains(upper," CREATE "){return value,nil}};return"",ErrInvalid}

func(d *SQLLogicalDumper)writeTableRows(ctx context.Context,queryer sqlQueryer,database,table string,destination io.Writer,rowLimit uint64)(uint64,error){order,err:=d.tableOrder(ctx,queryer,database,table);if err!=nil{return 0,err};query:="SELECT * FROM "+quoteSQLIdentifier(database)+"."+quoteSQLIdentifier(table)+" ORDER BY "+strings.Join(order,",");rows,err:=queryer.QueryContext(ctx,query);if err!=nil{return 0,err};defer rows.Close();columns,err:=rows.Columns();if err!=nil{return 0,err};types,err:=rows.ColumnTypes();if err!=nil{return 0,err};if len(columns)==0||len(columns)!=len(types){return 0,ErrInvalid};columnList:=make([]string,len(columns));for index,column:=range columns{if !validDatabaseName(column){return 0,ErrInvalid};columnList[index]=quoteSQLIdentifier(column)};var count uint64;for rows.Next(){if count>=rowLimit{return 0,migrationCapacityError()};values:=make([]any,len(columns));destinations:=make([]any,len(columns));for index:=range values{destinations[index]=&values[index]};if err:=rows.Scan(destinations...);err!=nil{return 0,err};encoded:=make([]string,len(values));for index,value:=range values{encoded[index],err=encodeSQLValue(value,types[index].DatabaseTypeName(),d.maximumValueBytes);if err!=nil{return 0,err}};if _,err:=fmt.Fprintf(destination,"INSERT INTO %s (%s) VALUES (%s);\n",quoteSQLIdentifier(table),strings.Join(columnList,","),strings.Join(encoded,","));err!=nil{return 0,err};count++};return count,rows.Err()}

func(d *SQLLogicalDumper)tableOrder(ctx context.Context,queryer sqlQueryer,database,table string)([]string,error){rows,err:=queryer.QueryContext(ctx,`SELECT COLUMN_NAME FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA=? AND TABLE_NAME=? AND CONSTRAINT_NAME='PRIMARY' ORDER BY ORDINAL_POSITION`,database,table);if err!=nil{return nil,err};values:=[]string{};for rows.Next(){var name string;if err:=rows.Scan(&name);err!=nil{rows.Close();return nil,err};if !validDatabaseName(name){rows.Close();return nil,ErrInvalid};values=append(values,quoteSQLIdentifier(name))};if err:=rows.Err();err!=nil{rows.Close();return nil,err};rows.Close();if len(values)>0{return values,nil};rows,err=queryer.QueryContext(ctx,`SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=? AND TABLE_NAME=? ORDER BY ORDINAL_POSITION`,database,table);if err!=nil{return nil,err};for rows.Next(){var name string;if err:=rows.Scan(&name);err!=nil{rows.Close();return nil,err};if !validDatabaseName(name){rows.Close();return nil,ErrInvalid};values=append(values,quoteSQLIdentifier(name))};if err:=rows.Err();err!=nil{rows.Close();return nil,err};rows.Close();if len(values)==0{return nil,ErrInvalid};return values,nil}

func(d *SQLLogicalDumper)writeTriggers(ctx context.Context,queryer sqlQueryer,database string,destination io.Writer)(uint64,error){rows,err:=queryer.QueryContext(ctx,`SELECT TRIGGER_NAME,ACTION_TIMING,EVENT_MANIPULATION,EVENT_OBJECT_TABLE,ACTION_STATEMENT FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=? ORDER BY TRIGGER_NAME`,database);if err!=nil{return 0,err};defer rows.Close();var count uint64;for rows.Next(){var name,timing,event,table,statement string;if err:=rows.Scan(&name,&timing,&event,&table,&statement);err!=nil{return 0,err};if !validDatabaseName(name)||!validDatabaseName(table)||(timing!="BEFORE"&&timing!="AFTER")||(event!="INSERT"&&event!="UPDATE"&&event!="DELETE"){return 0,ErrInvalid};if _,err:=fmt.Fprintf(destination,"DELIMITER ;;\nDROP TRIGGER IF EXISTS %s;;\nCREATE TRIGGER %s %s %s ON %s FOR EACH ROW %s;;\nDELIMITER ;\n",quoteSQLIdentifier(name),quoteSQLIdentifier(name),timing,event,quoteSQLIdentifier(table),trimSQLTerminator(statement));err!=nil{return 0,err};count++};return count,rows.Err()}

func(d *SQLLogicalDumper)writeRoutines(ctx context.Context,queryer sqlQueryer,database string,destination io.Writer)(uint64,error){rows,err:=queryer.QueryContext(ctx,`SELECT ROUTINE_NAME,ROUTINE_TYPE FROM information_schema.ROUTINES WHERE ROUTINE_SCHEMA=? ORDER BY ROUTINE_TYPE,ROUTINE_NAME`,database);if err!=nil{return 0,err};type routine struct{name,kind string};values:=[]routine{};for rows.Next(){var value routine;if err:=rows.Scan(&value.name,&value.kind);err!=nil{rows.Close();return 0,err};values=append(values,value)};if err:=rows.Err();err!=nil{rows.Close();return 0,err};rows.Close();var count uint64;for _,value:=range values{if !validDatabaseName(value.name)||(value.kind!="PROCEDURE"&&value.kind!="FUNCTION"){return 0,ErrInvalid};create,err:=d.showCreate(ctx,queryer,value.kind,database,value.name);if err!=nil{return 0,err};if _,err:=fmt.Fprintf(destination,"DELIMITER ;;\nDROP %s IF EXISTS %s;;\n%s;;\nDELIMITER ;\n",value.kind,quoteSQLIdentifier(value.name),trimSQLTerminator(create));err!=nil{return 0,err};count++};return count,nil}

func(d *SQLLogicalDumper)writeEvents(ctx context.Context,queryer sqlQueryer,database string,destination io.Writer)(uint64,error){rows,err:=queryer.QueryContext(ctx,`SELECT EVENT_NAME FROM information_schema.EVENTS WHERE EVENT_SCHEMA=? ORDER BY EVENT_NAME`,database);if err!=nil{return 0,err};names:=[]string{};for rows.Next(){var name string;if err:=rows.Scan(&name);err!=nil{rows.Close();return 0,err};names=append(names,name)};if err:=rows.Err();err!=nil{rows.Close();return 0,err};rows.Close();var count uint64;for _,name:=range names{if !validDatabaseName(name){return 0,ErrInvalid};create,err:=d.showCreate(ctx,queryer,"EVENT",database,name);if err!=nil{return 0,err};if _,err:=fmt.Fprintf(destination,"DELIMITER ;;\nDROP EVENT IF EXISTS %s;;\n%s;;\nDELIMITER ;\n",quoteSQLIdentifier(name),trimSQLTerminator(create));err!=nil{return 0,err};count++};return count,nil}

func scanStringRow(rows *sql.Rows)([]string,error){columns,err:=rows.Columns();if err!=nil{return nil,err};raw:=make([]sql.RawBytes,len(columns));targets:=make([]any,len(columns));for index:=range raw{targets[index]=&raw[index]};if err:=rows.Scan(targets...);err!=nil{return nil,err};values:=make([]string,len(raw));for index:=range raw{values[index]=string(raw[index])};return values,nil}
func encodeSQLValue(value any,databaseType string,maximum int)(string,error){if value==nil{return"NULL",nil};switch typed:=value.(type){case bool:if typed{return"1",nil};return"0",nil;case int64:return strconv.FormatInt(typed,10),nil;case uint64:return strconv.FormatUint(typed,10),nil;case float64:return strconv.FormatFloat(typed,'g',-1,64),nil;case time.Time:return quoteSQLString(typed.UTC().Format("2006-01-02 15:04:05.999999")),nil;case string:if len(typed)>maximum{return"",migrationCapacityError()};return quoteSQLString(typed),nil;case []byte:if len(typed)>maximum{return"",migrationCapacityError()};if binaryDatabaseType(databaseType){return"X'"+hex.EncodeToString(typed)+"'",nil};return quoteSQLString(string(typed)),nil;default:return"",ErrInvalid}}
func binaryDatabaseType(value string)bool{upper:=strings.ToUpper(value);return strings.Contains(upper,"BINARY")||strings.Contains(upper,"BLOB")||upper=="BIT"||upper=="GEOMETRY"}
func quoteSQLString(value string)string{var output strings.Builder;output.WriteByte('\'');for _,character:=range value{switch character{case 0:output.WriteString(`\0`);case'\n':output.WriteString(`\n`);case'\r':output.WriteString(`\r`);case'\\':output.WriteString(`\\`);case'\'':output.WriteString(`\'`);case 26:output.WriteString(`\Z`);default:output.WriteRune(character)}};output.WriteByte('\'');return output.String()}
func quoteSQLIdentifier(value string)string{return"`"+strings.ReplaceAll(value,"`","``")+"`"}
func validDatabaseName(value string)bool{return value!=""&&len(value)<=191&&!strings.ContainsRune(value,0)&&!strings.ContainsAny(value,"/\\")}
func safeSQLToken(value,fallback string)string{if value==""{return fallback};for _,character:=range value{if(character<'a'||character>'z')&&(character<'A'||character>'Z')&&(character<'0'||character>'9')&&character!='_'{return fallback}};return value}
func trimSQLTerminator(value string)string{return strings.TrimSuffix(strings.TrimSpace(value),";")}
func migrationCapacityError()error{return errors.Join(migration.ErrCapacity,errors.New("cyberpanel extractor: logical dump exceeds approved limits"))}

var _ DatabaseDumper=(*SQLLogicalDumper)(nil)
